import json
from pathlib import Path

root = Path(__file__).parent / 'translations/ro/full/chunks'
translations = {
    't000056': 'Capitolul 5 — Cavalerul virtual: DQ 2.0',
    't000057': 'În lumea luminată de neoane a anului 2085, unde realitatea și fantezia sunt despărțite doar de o pereche de ochelari VR, Alonso Quijano nu mai știe care este una și care este cealaltă. Odinioară un dezvoltator strălucit de jocuri video, Alonso a petrecut ani întregi creând cel mai captivant joc de fantezie medievală văzut vreodată. Creația sa, „Knight’s Dominion”, a devenit un succes mondial, permițându-le jucătorilor să pășească într-o lume medievală pe deplin realizată, unde puteau lupta cu dragoni, se puteau duela cu vrăjitori și puteau ajunge cavaleri nobili.',
    't000058': 'Dar, în timp ce milioane de oameni se jucau de plăcere, Alonso a mers puțin prea departe. Granițele dintre lumea lui imaginară și cea reală au început să se estompeze. Orele s-au transformat în zile, iar zilele în săptămâni, pe măsură ce petrecea tot mai mult timp în propria creație. Ce începuse ca un teren de joacă digital a devenit o obsesie. Curând, Alonso a încetat să mai proiecteze doar lumea aceea — a început să trăiască în ea.',
    't000059': 'Așa a apărut Don Quijote 2.0, noua identitate a lui Alonso. Echipat cu o cască VR de ultimă generație, controlere de mișcare și un costum haptic pentru întregul corp, care îi permitea să simtă fiecare lovitură de sabie și de scut, Alonso a început să se vadă nu ca un simplu dezvoltator, ci ca un cavaler adevărat. Iar în această nouă realitate virtuală nu existau hotare între joc și viața din afara lui.',
    't000060': 'Pentru colegii săi, transformarea lui Alonso era de neînțeles. Cunoscut cândva pentru mintea ageră și replica rapidă, își petrecea acum zilele vorbind despre înfrângerea dragonilor și salvarea prințeselor din turnuri virtuale. Cel mai bun prieten al lui, Sancho, și el dezvoltator de jocuri, a încercat să-l readucă la realitate, dar Alonso era deja prea departe. Credea cu adevărat că se afla într-o mare misiune de salvare a lumii de forțele răului — și că aceste forțe scăpaseră cumva din jocul lui în lumea reală.',
    't000061': 'Cu casca VR lipită mereu de cap ca un coif de cavaler, Alonso mergea țanțoș pe străzile orașului, văzând peste ele peisajele digitale din Knight’s Dominion. Fiecare clădire devenea un castel, fiecare stație de autobuz, un avanpost medieval. Iar cetățenii obișnuiți? În mintea lui Alonso, erau aliați sau dușmani, după cum se uitau la el.',
    't000062': 'Nu a trecut mult până când Alonso și-a început „aventurile” cu adevărat. Înarmat cu sabia virtuală și cu un controler de mișcare pe care îl credea scut, a pornit să ucidă dragonii care îi chinuiau orașul. Problema? Dragonii nu erau deloc dragoni. Erau autobuze, stâlpi de iluminat sau, într-o ocazie nefericită, un camion de livrări destul de mare. Dar pentru Alonso, aceste fiare metalice erau dușmani amenințători, gata să-i distrugă regatul.',
    't000063': 'Amăgirile lui au atins apogeul într-o după-amiază fatidică, atunci când Alonso s-a găsit în fața unui zgârie-nori modern și elegant, pe care nu îl putea descrie decât ca pe turnul unui vrăjitor malefic. În realitate, era doar sediul unei firme de tehnologie. În ochii lui Alonso, era vizuina lui Maldor Magul, un stăpân AI răufăcător despre care credea că scăpase din joc și își folosea acum puterile digitale pentru a corupe lumea reală.',
    't000064': '„Rămâi pe loc, vrăjitor nemernic!” a tunat Alonso, fluturând sabia invizibilă spre clădirea de sticlă.',
    't000065': 'Sancho a sosit chiar atunci, după ce îl localizase pe Alonso cu GPS-ul telefonului (pe care Alonso îl credea harta sa fermecată). Sancho, care renunțase de câteva săptămâni să se mai certe cu el, s-a rezemat degajat de o bancă, cu brațele încrucișate, urmărind scena.',
    't000066': '„Alonso — ăă, vreau să spun, Don Quijote — ce faci mai exact?” a întrebat Sancho, deși știa deja răspunsul.',
    't000067': '„Asaltez turnul lui Maldor!” a răspuns Alonso cu glas hotărât. A îndreptat controlerul VR spre clădire de parcă ar fi fost un toiag puternic. „I-am urmărit magia malefică până aici. Aici se ascunde. Dar nu te teme, Sancho, căci astăzi îl vom învinge!”',
    't000068': 'Sancho a oftat. „Bine. Și cum anume plănuiești să învingi un... zgârie-nori?”',
    't000069': 'Alonso i-a aruncat o privire piezișă, de parcă ar fi fost surprins că Sancho nu pricepuse. „Cu Sabia Luminii Eterne, desigur”, a spus, ridicând controlerul de mișcare ca și cum ar fi strălucit într-o lumină misterioasă pe care numai el o putea vedea.',
    't000070': 'Sancho și-a stăpânit un zâmbet și a dat din cap. „Bine, șefule, numai să nu te omori, da? Data trecută era cât pe ce să te calce un «dragon»”, a spus el, amintindu-i de întâmplarea cu autobuzul de cu o săptămână înainte.',
    't000071': 'Cu o mișcare dramatică a sabiei sale invizibile, Alonso a pornit în goană spre clădire, dar s-a oprit brusc când costumul haptic i-a trimis o vibrație prin corp. Sistemul VR declanșase un „avertisment”: apăruse un „paznic al turnului”. În realitate, era doar un agent de pază venit să vadă de ce alerga spre clădire un bărbat în costum haptic.',
    't000072': '„Înapoi, fiară mârșavă!” a strigat Alonso către paznicul nedumerit, care nu înțelegea deloc ce se petrecea.',
    't000073': 'Sancho a intervenit repede și l-a tras pe Alonso deoparte înainte ca lucrurile să se agraveze. „Îmi pare rău pentru el”, i-a murmurat paznicului, „se... ăă... joacă de-a personajele. E foarte prins de asta. Știți cum e.”',
    't000074': 'Pe când se îndepărtau, Alonso s-a întors spre Sancho, încă încredințat că scăpaseră la limită de o pieire sigură. „Paznicul acela își poate schimba înfățișarea, Sancho. Fără îndoială, e o slugă a lui Maldor.”',
    't000075': '„Sigur, sigur”, a răspuns Sancho, bătându-l pe umăr. „Dar poate lăsăm pe altă zi atacurile eroice, da? Nu cred că suntem pregătiți să înfruntăm încă un dragon în toată puterea cuvântului.”',
    't000076': 'În ciuda strădaniilor lui Sancho de a-l ține pe Alonso cu picioarele pe pământ, existau clipe când chiar și el se lăsa prins de fantezie. Era greu să nu o facă, mai ales când Alonso vorbea cu atâta convingere. La urma urmei, nu era și lumea reală absurdă uneori? Poate că Alonso avea dreptate când spunea că dragonii se pot ascunde oriunde — nu la propriu, ci în felul în care corporațiile corupte, magnații lacomi ai tehnologiei și conducătorii însetați de putere pot eroda treptat societatea.',
    't000077': 'Amăgirea lui Alonso devenea, în felul ei straniu, un memento că nu toate bătăliile sunt vizibile. Uneori, adevărații răufăcători se ascund în spatele clădirilor elegante de birouri și al ecranelor digitale. Poate că lumea nu avea nevoie de încă un realist bine ancorat în realitate ca Sancho, ci de cineva precum Don Quijote — dispus să atace dușmani invizibili doar cu o sabie de jucărie și cu inima plină de curaj.',
    't000078': 'În timp ce cei doi prieteni mergeau spre casă, Alonso s-a oprit brusc și a arătat spre orizont, unde soarele începea să apună în spatele zgârie-norilor. În lumina care se stingea, orașul era scăldat într-o strălucire aurie.',
    't000079': '„Sancho”, a spus încet, „o vezi?”',
    't000080': 'Sancho a ridicat o sprânceană. „Ce să văd?”',
    't000081': '„Fortăreața”, a șoptit Alonso. „Următoarea noastră misiune ne așteaptă.”',
    't000082': 'Sancho a privit linia clădirilor și a văzut doar siluetele lor. Dar, pentru o clipă, și-a îngăduit să-și imagineze ce vedea Alonso — castele, turnuri și dragoni învârtindu-se în depărtare. Iar pentru o secundă a zâmbit.',
    't000083': '„Da, șefule”, a spus Sancho cu blândețe. „O văd.”',
    't000084': 'Și astfel au pornit din nou la drum, doi eroi improbabili într-o misiune fără sfârșit de a salva o lume care nu știa că are nevoie să fie salvată.',
    't000085': 'Capitolul 6 — Don Quijote în spațiu: Cavalerul cosmic',
    't000086': 'În viitorul îndepărtat, omenirea a ieșit în cele din urmă din hotarele Pământului și a colonizat regiunile îndepărtate ale galaxiei. Călătoria interstelară este obișnuită, iar stațiile spațiale uriașe plutesc precum niște colosi metalici, risipiți prin cosmos. În mijlocul tuturor acestora, plutind liniștit prin vidul întunecat, se află Don Quijote, un om cu o singură misiune: să aducă pace și dreptate în galaxie.',
    't000087': 'Don Quijote nu a fost dintotdeauna autoproclamatul cavaler al cosmosului. Cândva era Alonso Quijano, un astronaut și om de știință foarte bine pregătit, însărcinat cu misiuni științifice importante. Dar, după ce a petrecut prea mult timp în misiuni spațiale îndepărtate, rupt luni în șir de contactul cu oamenii, mintea lui a început să se destrame. Vidul nesfârșit al spațiului, imensitatea stelelor și zumzetul constant al navei și-au spus cuvântul. Alonso s-a pierdut în vechile povești despre cavaleri, misiuni și lupte între bine și rău, pe care le luase cu el ca să treacă timpul. Undeva pe parcurs, poveștile s-au contopit cu realitatea, iar el a devenit Don Quijote, Cavalerul Cosmosului.',
    't000088': 'Îmbrăcat în costumul spațial pe care îl crede o armură strălucitoare, Don Quijote călătorește acum prin univers în nava lui, Rocinante, un vas rezistent, cu propulsoare ruginite și sisteme de navigație defecte. Pentru oricine altcineva, Rocinante este o relicvă a unei epoci mai vechi a explorării spațiale; pentru Don Quijote, este un armăsar viteaz, gata să-l poarte în orice bătălie. Misiunea lui e simplă — deși cu totul iluzorie: să scape galaxia de forțele răului și să aducă pace printre stele.',
    't000089': 'Fiecare cavaler are, desigur, nevoie de un scutier, iar Don Quijote are unul — deși nu e om. Tovarășul lui credincios este Sancho, un robot asistent binevoitor, bazat pe inteligență artificială. Sancho a fost programat să ajute la misiuni științifice, reparații și întreținerea navei. Însă, în ultima vreme, funcția lui principală pare să fie aceea de a-l împiedica pe Don Quijote să zboare din greșeală într-o gaură neagră sau să confunde resturile spațiale cu dușmani cosmici. Sancho poate că este robot, dar nici el nu se poate opri din a simți că a fost târât într-o aventură fără sfârșit alături de un om care și-a pierdut cu totul mințile.',
    't000090': '„Misiunile” lor sunt la fel de extravagante pe cât v-ați aștepta. Una dintre ele îi duce la un grup de stații spațiale abandonate, aflate pe orbita unei planete îndepărtate. Pentru un observator obișnuit, acestea sunt doar carcase goale lăsate de o generație mai veche de exploratori. Dar pentru Don Quijote sunt „Morile de vânt ale galaxiei” și sunt, fără îndoială, periculoase. „Sancho, le vezi?” întreabă Don Quijote, privind prin hublou spre structurile în descompunere.',
    't000091': '„Ce să văd, domnule?” răspunde Sancho, cu vocea lui robotică încărcată de nedumerire politicoasă.',
    't000092': '„Morile de vânt cosmice”, explică Don Quijote, cu glas plin de convingere. „Acele turnuri răsucite ale răului care îi amenință pe oamenii buni ai galaxiei. Trebuie să le distrugem înainte să facă prăpăd printre stele!”',
    't000093': 'Sancho încearcă să fie rezonabil: „Sunt stații spațiale abandonate, domnule. Nu a mai locuit nimeni acolo de zeci de ani. Nu reprezintă niciun pericol.”',
    't000094': 'Dar Don Quijote nu se lasă înduplecat. „Prostii, Sancho! Numai un cavaler adevărat poate vedea primejdia ascunsă sub învelișul lor ruginit. Pregătește nava de luptă!”',
    't000095': 'Senzorii lui Sancho clipesc ușor alarmați când Don Quijote împinge propulsoarele la putere maximă și îndreaptă Rocinante direct spre cea mai apropiată stație spațială. Pentru Sancho, este o construcție veche, gata să se prăbușească — doar fier vechi plutitor. Pentru Don Quijote, este un dușman uriaș, un gigant cosmic care trebuie învins.',
    't000096': 'Pe măsură ce se apropie de „dușman”, Don Quijote apucă tăietorul cu plasmă, botezat de el Sabia Stelelor, și se pregătește să iasă pentru ceea ce își imaginează că va fi un duel spațial vitejesc. „Stai, dușman puternic!” strigă el ieșind din sas, plutind spre stație cu toată grația unui cavaler încercat care pornește la atac.',
    't000097': 'Din păcate, bătălia este mult mai puțin dramatică decât se așteaptă Don Quijote. În clipa când atinge suprafața stației, bocancii magnetici ai costumului îl fixează pe loc, iar sabia — o torță cu plasmă inofensivă — se stinge cu un pârâit. „Gigantul” rămâne tăcut, neclintit de încercările lui de a-i tăia carcasa.',
    't000098': '„Domnule”, spune Sancho prin sistemul de comunicații, „cred că stația este, de fapt, nefuncțională. Nu se află niciun dragon aici.”',
    't000099': '„Dragon?” pufnește Don Quijote. „Acesta nu este un simplu dragon, Sancho! Este o fortăreață a răului cosmic și o voi dărâma cu propriile mâini!”',
    't000100': 'După o oră de efort zadarnic, Don Quijote acceptă fără tragere de inimă să părăsească stația, dar nu înainte de a proclama victoria. „Am schilodit fiara astăzi, Sancho. Să fie o lecție pentru toate forțele întunericului care ar cuteza să stea în calea dreptății!”',
    't000101': 'Sancho, obișnuit deja cu asemenea „victorii”, răspunde doar: „Desigur, domnule. Foarte bine făcut.”',
    't000102': 'Aventurile lor continuă, devenind adesea tot mai absurde. Odată, Don Quijote a confundat un mic câmp de asteroizi cu o armată de „șerpi spațiali”. A dus Rocinante chiar în mijlocul lor, hotărât să-i ucidă pe toți, în timp ce Sancho se grăbea să reconfigureze scuturile navei și să-i apere de primejdia foarte reală de a fi zdrobiți de resturi. „Nu te teme, Sancho!” a strigat Don Quijote prin sistemul de comunicații. „Șerpii aceștia vor simți oțelul rece al sabiei mele!”',
    't000103': '„Domnule, trebuie să vă amintesc că asteroizii sunt obiecte fără viață”, a intervenit calm Sancho, schimbând cursul navei chiar la timp pentru a evita o coliziune.',
    't000104': 'Și a mai fost clipa când Don Quijote a întâlnit o cometă care străbătea spațiul. Pentru oricine altcineva, era un fenomen ceresc natural. Pentru el, era un „dragon de foc cosmic”, o fiară maiestuoasă ce trebuia oprită înainte să incendieze un întreg sistem stelar. „Sancho, repede! Pregătește tunurile ionice!” a poruncit Don Quijote.',
    't000105': '„Domnule, nu avem tunuri ionice. Aceasta este o navă de cercetare”, a răspuns Sancho.',
    't000106': '„Nu contează! O voi doborî cu sabia mea!” Don Quijote, cât se poate de serios, se pregătea să se arunce în spațiu pentru a înfrunta cometa direct.',
    't000107': 'În toate aceste aventuri absurde, Sancho a continuat să îl urmeze pe Don Quijote, corectând cursul, redirecționând energia și administrând sistemele navei. Deși programarea lui Sancho nu includea înțelegerea amăgirilor omenești, între ei se legase o relație ciudată. Sancho nu putea pătrunde pe deplin complexitatea fanteziilor lui Don Quijote, dar misiunea omului avea ceva straniu de nobil — chiar dacă era cu totul greșit îndreptată.',
    't000108': 'În felul lui, Don Quijote reprezenta ceva ce nici cea mai avansată inteligență artificială nu putea înțelege pe deplin: speranța. Ideea că, în fața unor șanse copleșitoare și a vastității reci și indiferente a spațiului, un singur om putea crede în onoare, dreptate și cavaleri cosmici luptând pentru un bine mai mare.',
    't000109': 'Pe când pluteau prin galaxie, Sancho se întreba dacă nu cumva Don Quijote nu greșea întru totul. La urma urmei, universul era plin de forțe întunecate — corporații lacome care colonizau planete, inteligențe artificiale scăpate de sub control care preluau sisteme întregi și războaie fără sfârșit între facțiuni. Poate că universul avea cu adevărat nevoie de un cavaler în armură spațială strălucitoare, chiar dacă acesta mânuia un tăietor cu plasmă și confunda asteroizii cu dragonii.',
    't000110': 'Și astfel, cu motoarele lui Rocinante torcând încet, Don Quijote și Sancho au călătorit mai adânc în cosmos, mereu în căutare de aventuri noi, bătălii noi și feluri noi de a aduce dreptatea printre stele.',
    't000111': '„Înainte, Sancho!” a strigat Don Quijote din cabina de pilotaj. „Mai sunt rele de învins și dragoni de ucis!”',
    't000112': '„Da, domnule”, a răspuns Sancho, ajustând cursul navei. „Mai sunt dragoni.”',
    't000113': 'Iar în tăcerea spațiului, perechea neașteptată și-a continuat misiunea — doi visători într-un univers care avea disperată nevoie de puțină imaginație.',
    't000114': 'Concluzie',
}
for name in ('0007', '0008', '0009', '0010'):
    path = root / f'{name}.json'
    data = json.loads(path.read_text(encoding='utf-8'))
    for item in data['segments']:
        item['translation'] = translations[item['id']]
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
